def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1
    opp_def = sum(1 for x in opp if x == 'D')
    last_opp = opp[-1]
    last_me = me[-1]
    if n < 3:
        return 'C'
    if opp_def == 0:
        return 'C'
    recent = opp[-5:]
    recent_def = sum(1 for x in recent if x == 'D')
    if recent_def == 0:
        return 'C'
    if last_opp == 'D' and last_me == 'C':
        if n >= 2 and opp[-2] == 'D':
            return 'D'
        return 'D' if rng.random() < 0.5 else 'C'
    if last_opp == 'D' and last_me == 'D':
        if recent_def >= 4:
            return 'D'
        return 'C' if rng.random() < 0.3 else 'D'
    if last_opp == 'C' and last_me == 'D':
        if recent_def <= 1:
            return 'C'
        return 'D' if rng.random() < 0.6 else 'C'
    if last_opp == 'C' and last_me == 'C':
        if recent_def >= 3:
            return 'D'
        return 'C'
    return 'C'
